#!/bin/sh
# コードの PlayerModel / RegulationModel に合わせたテーブル定義
set -e
psql -v ON_ERROR_STOP=1 -U postgres -d vrc <<SQL
create role anon nologin;
create role authenticator noinherit login password '${POSTGRES_PASSWORD}';
grant anon to authenticator;

create table "Player" (
  "ID" integer generated by default as identity primary key,
  "Name" text not null,
  "EntryStatus" integer not null default 0,
  "StaffStatus" boolean not null default false,
  "ExpStatus" integer not null default 0,
  "RegulationStatus" integer not null default 0,
  "JoinStatus" boolean not null default false
);

create table "Regulation" (
  "ID" integer primary key,
  "RegulationName" text
);
insert into "Regulation" ("ID", "RegulationName") values (1, 'テストレギュ1'), (2, 'テストレギュ2');

grant usage on schema public to anon;
grant select, insert, update on "Player" to anon;
grant usage, select on all sequences in schema public to anon;
grant select on "Regulation" to anon;
SQL
